(18, 'آموزش ضرب با کارت بازی', '', 'uploads/gallery/202509/gal_68d85076adec93.88582008.jpeg', 'activities', NULL, '2025-09-27 21:00:38'),
(24, 'بدون عنوان - 1', '', 'uploads/gallery/202509/gal_68daca81cb6763.39204728.jpg', 'artwork', NULL, '2025-09-29 18:05:53'),
(26, 'بدون عنوان - 3', '', 'uploads/gallery/202509/gal_68daca833e3207.12409628.jpg', 'artwork', NULL, '2025-09-29 18:05:55'),
