INSERT INTO `game_templates` (`id`, `name`, `category`, `description`, `difficulty`, `duration`, `template_code`, `preview_image`, `tags`, `usage_count`, `is_featured`, `is_active`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'جمع و تفریق ساده', 'math', 'بازی تعاملی برای تمرین جمع و تفریق اعداد تک رقمی', 'آسان', '10-15 دقیقه', '<!DOCTYPE html><html dir=\"rtl\" lang=\"fa\"><head><meta charset=\"utf-8\"><title>جمع و تفریق</title><style>body{font-family:Tahoma;text-align:center;padding:20px;background:#f0f8ff}h1{color:#2c5aa0}button{padding:10px 20px;background:#4CAF50;color:white;border:none;border-radius:5px;font-size:16px;cursor:pointer}</style></head><body><h1>بازی جمع و تفریق</h1><div id=\"question\"></div><div id=\"options\"></div><div id=\"score\">امتیاز: 0</div><script>let score=0;function newQuestion(){let a=Math.floor(Math.random()*10)+1;let b=Math.floor(Math.random()*10)+1;let isAdd=Math.random()>0.5;let question=isAdd?`${a} + ${b}`:a>=b?`${a} - ${b}`:`${b} - ${a}`;let answer=isAdd?a+b:a>=b?a-b:b-a;document.getElementById(\"question\").innerHTML=`<h2>${question} = ?</h2>`;let options=[answer];while(options.length<3){let wrong=Math.floor(Math.random()*20)+1;if(!options.includes(wrong))options.push(wrong);}options.sort(()=>Math.random()-0.5);document.getElementById(\"options\").innerHTML=options.map(opt=>`<button onclick=\"checkAnswer(${opt},${answer})\">${opt}</button>`).join(\" \");}function checkAnswer(selected,correct){if(selected===correct){score++;alert(\"آفرین! جواب درست بود\");document.dispatchEvent(new CustomEvent(\"game:score\",{detail:{score:score}}));}else{alert(`متأسفانه جواب غلط بود. جواب درست: ${correct}`);}document.getElementById(\"score\").textContent=\"امتیاز: \"+score;newQuestion();}document.addEventListener(\"DOMContentLoaded\",()=>{document.dispatchEvent(new CustomEvent(\"game:start\"));newQuestion();});</script></body></html>', NULL, '[\"ریاضی\", \"جمع\", \"تفریق\", \"آسان\"]', 0, 1, 1, NULL, '2025-08-21 22:18:26', '2025-08-21 22:18:26'),
(2, 'شکار کلمات', 'persian', 'بازی یافتن کلمات در میان حروف برای تقویت املا', 'متوسط', '15-20 دقیقه', '<!DOCTYPE html><html dir=\"rtl\" lang=\"fa\"><head><meta charset=\"utf-8\"><title>شکار کلمات</title><style>body{font-family:Tahoma;text-align:center;padding:20px;background:#fff8dc}h1{color:#8b4513}.grid{display:grid;grid-template-columns:repeat(8,40px);gap:2px;justify-content:center;margin:20px auto}.cell{width:40px;height:40px;background:#ffebcd;border:2px solid #deb887;display:flex;align-items:center;justify-content:center;font-weight:bold;cursor:pointer}.cell:hover{background:#f0e68c}</style></head><body><h1>شکار کلمات</h1><div id=\"words\">کلمات: کتاب، درس، مدرسه</div><div class=\"grid\" id=\"grid\"></div><div id=\"found\">پیدا شده: </div><script>const words=[\"کتاب\",\"درس\",\"مدرسه\"];const letters=\"کتابدرسمهلنوپقیئ\";let grid=[];let foundWords=[];function createGrid(){for(let i=0;i<64;i++){grid.push(letters[Math.floor(Math.random()*letters.length)]);}placeWords();displayGrid();}function placeWords(){words.forEach(word=>{let placed=false;let attempts=0;while(!placed&&attempts<50){let row=Math.floor(Math.random()*8);let col=Math.floor(Math.random()*(9-word.length));let canPlace=true;for(let i=0;i<word.length;i++){if(grid[row*8+col+i]!==letters[Math.floor(Math.random()*letters.length)]){canPlace=false;break;}}if(canPlace){for(let i=0;i<word.length;i++){grid[row*8+col+i]=word[i];}placed=true;}attempts++;}});}function displayGrid(){const gridEl=document.getElementById(\"grid\");gridEl.innerHTML=\"\";grid.forEach((letter,index)=>{const cell=document.createElement(\"div\");cell.className=\"cell\";cell.textContent=letter;cell.onclick=()=>selectCell(index);gridEl.appendChild(cell);});}function selectCell(index){console.log(\"انتخاب شد:\",grid[index]);}document.addEventListener(\"DOMContentLoaded\",()=>{document.dispatchEvent(new CustomEvent(\"game:start\"));createGrid();});</script></body></html>', NULL, '[\"فارسی\", \"املا\", \"کلمات\", \"متوسط\"]', 0, 1, 1, NULL, '2025-08-21 22:18:26', '2025-08-21 22:18:26'),
(3, 'جمع و تفریق ساده', 'math', 'بازی تعاملی برای تمرین جمع و تفریق اعداد تک رقمی', 'آسان', '10-15 دقیقه', '<!DOCTYPE html><html dir=\"rtl\" lang=\"fa\"><head><meta charset=\"utf-8\"><title>جمع و تفریق</title><style>body{font-family:Tahoma;text-align:center;padding:20px;background:#f0f8ff}h1{color:#2c5aa0}button{padding:10px 20px;background:#4CAF50;color:white;border:none;border-radius:5px;font-size:16px;cursor:pointer}</style></head><body><h1>بازی جمع و تفریق</h1><div id=\"question\"></div><div id=\"options\"></div><div id=\"score\">امتیاز: 0</div><script>let score=0;function newQuestion(){let a=Math.floor(Math.random()*10)+1;let b=Math.floor(Math.random()*10)+1;let isAdd=Math.random()>0.5;let question=isAdd?`${a} + ${b}`:a>=b?`${a} - ${b}`:`${b} - ${a}`;let answer=isAdd?a+b:a>=b?a-b:b-a;document.getElementById(\"question\").innerHTML=`<h2>${question} = ?</h2>`;let options=[answer];while(options.length<3){let wrong=Math.floor(Math.random()*20)+1;if(!options.includes(wrong))options.push(wrong);}options.sort(()=>Math.random()-0.5);document.getElementById(\"options\").innerHTML=options.map(opt=>`<button onclick=\"checkAnswer(${opt},${answer})\">${opt}</button>`).join(\" \");}function checkAnswer(selected,correct){if(selected===correct){score++;alert(\"آفرین! جواب درست بود\");document.dispatchEvent(new CustomEvent(\"game:score\",{detail:{score:score}}));}else{alert(`متأسفانه جواب غلط بود. جواب درست: ${correct}`);}document.getElementById(\"score\").textContent=\"امتیاز: \"+score;newQuestion();}document.addEventListener(\"DOMContentLoaded\",()=>{document.dispatchEvent(new CustomEvent(\"game:start\"));newQuestion();});</script></body></html>', NULL, '[\"ریاضی\", \"جمع\", \"تفریق\", \"آسان\"]', 0, 1, 1, NULL, '2025-08-21 22:22:35', '2025-08-21 22:22:35'),
(4, 'شکار کلمات', 'persian', 'بازی یافتن کلمات در میان حروف برای تقویت املا', 'متوسط', '15-20 دقیقه', '<!DOCTYPE html><html dir=\"rtl\" lang=\"fa\"><head><meta charset=\"utf-8\"><title>شکار کلمات</title><style>body{font-family:Tahoma;text-align:center;padding:20px;background:#fff8dc}h1{color:#8b4513}.grid{display:grid;grid-template-columns:repeat(8,40px);gap:2px;justify-content:center;margin:20px auto}.cell{width:40px;height:40px;background:#ffebcd;border:2px solid #deb887;display:flex;align-items:center;justify-content:center;font-weight:bold;cursor:pointer}.cell:hover{background:#f0e68c}</style></head><body><h1>شکار کلمات</h1><div id=\"words\">کلمات: کتاب، درس، مدرسه</div><div class=\"grid\" id=\"grid\"></div><div id=\"found\">پیدا شده: </div><script>const words=[\"کتاب\",\"درس\",\"مدرسه\"];const letters=\"کتابدرسمهلنوپقیئ\";let grid=[];let foundWords=[];function createGrid(){for(let i=0;i<64;i++){grid.push(letters[Math.floor(Math.random()*letters.length)]);}placeWords();displayGrid();}function placeWords(){words.forEach(word=>{let placed=false;let attempts=0;while(!placed&&attempts<50){let row=Math.floor(Math.random()*8);let col=Math.floor(Math.random()*(9-word.length));let canPlace=true;for(let i=0;i<word.length;i++){if(grid[row*8+col+i]!==letters[Math.floor(Math.random()*letters.length)]){canPlace=false;break;}}if(canPlace){for(let i=0;i<word.length;i++){grid[row*8+col+i]=word[i];}placed=true;}attempts++;}});}function displayGrid(){const gridEl=document.getElementById(\"grid\");gridEl.innerHTML=\"\";grid.forEach((letter,index)=>{const cell=document.createElement(\"div\");cell.className=\"cell\";cell.textContent=letter;cell.onclick=()=>selectCell(index);gridEl.appendChild(cell);});}function selectCell(index){console.log(\"انتخاب شد:\",grid[index]);}document.addEventListener(\"DOMContentLoaded\",()=>{document.dispatchEvent(new CustomEvent(\"game:start\"));createGrid();});</script></body></html>', NULL, '[\"فارسی\", \"املا\", \"کلمات\", \"متوسط\"]', 0, 1, 1, NULL, '2025-08-21 22:22:35', '2025-08-21 22:22:35');
