(439, 158, 'کدامیک از ویژگی های تمدن نیست؟', 'mcq', '{\"options\": [{\"text\": \"خط\", \"correct\": false}, {\"text\": \"دفاع از سرزمین\", \"correct\": true}, {\"text\": \"حکومت و فرمانروا\", \"correct\": false}, {\"text\": \"تقسیم کار و مهارت در کارها\", \"correct\": false}]}', 1, 19, 1, '2025-12-14 22:29:02', '2025-12-14 22:29:02'),
(440, 158, 'انسان ابتدا چگونه آتش را کشف کرد؟', 'mcq', '{\"options\": [{\"text\": \"رعد و برق\", \"correct\": true}, {\"text\": \"بر هم زدن بعضی سنگ ها\", \"correct\": false}, {\"text\": \"مالیدن چوب ها روی هم\", \"correct\": false}, {\"text\": \"کبریت\", \"correct\": false}]}', 1, 20, 1, '2025-12-14 22:31:04', '2025-12-14 22:31:04'),
(441, 159, 'به پستی و بلندی های زمین چه می گویند؟', 'mcq', '{\"options\": [{\"text\": \"رشته کوه\", \"correct\": false}, {\"text\": \"نا همواری\", \"correct\": true}, {\"text\": \"همواری\", \"correct\": false}, {\"text\": \"جلگه\", \"correct\": false}]}', 1, 1, 1, '2026-02-24 08:35:29', '2026-02-24 08:35:29'),
(442, 159, 'به کوه هایی که مثل زنجیر به هم متصلند چه می گویند؟', 'mcq', '{\"options\": [{\"text\": \"رشته کوه\", \"correct\": true}, {\"text\": \"کوهپایه\", \"correct\": false}, {\"text\": \"دامنه کوه\", \"correct\": false}, {\"text\": \"قله کوه\", \"correct\": false}]}', 1, 2, 1, '2026-02-24 08:37:15', '2026-02-24 08:37:15'),
(443, 159, 'بالاترین جای کوه و زمین های پایین کوه به ترتیب چه می گویند؟', 'mcq', '{\"options\": [{\"text\": \"قله - دامنه\", \"correct\": false}, {\"text\": \"دامنه - قله\", \"correct\": false}, {\"text\": \"کوهپایه - قله\", \"correct\": false}, {\"text\": \"قله- کوهپایه\", \"correct\": true}]}', 1, 3, 1, '2026-02-24 09:08:35', '2026-02-24 09:08:35'),
(444, 159, 'بلندترین قله ی ایران کدام است؟', 'mcq', '{\"options\": [{\"text\": \"البرز\", \"correct\": false}, {\"text\": \"زاگرس\", \"correct\": false}, {\"text\": \"دماوند\", \"correct\": true}, {\"text\": \"دنا\", \"correct\": false}]}', 1, 4, 1, '2026-02-24 09:10:06', '2026-02-24 09:10:06'),
(445, 159, 'به زمین های صاف و هموار چه می گویند؟', 'mcq', '{\"options\": [{\"text\": \"دشت\", \"correct\": true}, {\"text\": \"ناهمواری\", \"correct\": false}, {\"text\": \"همواری\", \"correct\": false}, {\"text\": \"همواری\", \"correct\": false}]}', 1, 5, 1, '2026-02-24 09:11:54', '2026-02-24 09:11:54'),
(446, 159, 'کدام جمله درست است؟', 'mcq', '{\"options\": [{\"text\": \"خاک همه ی دشت ها برای کشاورزی مناسب است.\", \"correct\": false}, {\"text\": \"بعضی از دشت ها برای کشاورزش مناسب و بعضی از دشت ها مناسب نیستند.\", \"correct\": true}, {\"text\": \"دشت ها برای کشاورزی نیستند.\", \"correct\": false}, {\"text\": \"در ایران دشت وجود ندارد.\", \"correct\": false}]}', 1, 6, 1, '2026-02-24 09:17:10', '2026-02-24 09:17:10'),
(447, 159, 'از به هم پیوستن جویبار چه چیزی بوجود می آید؟', 'mcq', '{\"options\": [{\"text\": \"جوی\", \"correct\": false}, {\"text\": \"دریا\", \"correct\": false}, {\"text\": \"رود\", \"correct\": true}, {\"text\": \"دریاچه\", \"correct\": false}]}', 1, 7, 1, '2026-02-24 09:18:32', '2026-02-24 09:18:32'),
(448, 159, 'به شن و ماسه و گل و لایی که رودها همراه خود می برند، چه می گویند؟', 'mcq', '{\"options\": [{\"text\": \"جلگه\", \"correct\": false}, {\"text\": \"رود\", \"correct\": false}, {\"text\": \"جویبار\", \"correct\": false}, {\"text\": \"آبرفت\", \"correct\": true}]}', 1, 8, 1, '2026-02-24 09:20:33', '2026-02-24 09:20:33'),
(449, 159, 'آبرفت پس از سالها انباشته شدن روی هم چه بوجود می آورد؟', 'mcq', '{\"options\": [{\"text\": \"جلگه\", \"correct\": true}, {\"text\": \"آبرفت\", \"correct\": false}, {\"text\": \"قله\", \"correct\": false}, {\"text\": \"دشت\", \"correct\": false}]}', 1, 9, 1, '2026-02-24 09:21:42', '2026-02-24 09:21:42'),
(450, 159, 'دو رشته کوه مهم ایران چه نام دارد؟', 'mcq', '{\"options\": [{\"text\": \"دنا و زرد کوه\", \"correct\": false}, {\"text\": \"البرز و زاگرس\", \"correct\": true}, {\"text\": \"کویر و لوت\", \"correct\": false}, {\"text\": \"گرگان و خوزستان\", \"correct\": false}]}', 1, 10, 1, '2026-02-24 09:22:57', '2026-02-24 09:22:57'),
