--
-- Table structure for table `student_xp`
--

CREATE TABLE `student_xp` (
  `id` int NOT NULL,
  `student_id` int NOT NULL,
  `math_xp` int DEFAULT '0',
  `science_xp` int DEFAULT '0',
  `persian_xp` int DEFAULT '0',
  `social_xp` int DEFAULT '0',
  `religion_xp` int DEFAULT '0',
  `podcast_xp` int NOT NULL DEFAULT '0',
  `dic_xp` int NOT NULL DEFAULT '0',
  `other_xp` int NOT NULL DEFAULT '0',
  `exam_xp` int NOT NULL DEFAULT '0',
  `total_xp` int GENERATED ALWAYS AS (((((((((coalesce(`math_xp`,0) + coalesce(`science_xp`,0)) + coalesce(`persian_xp`,0)) + coalesce(`social_xp`,0)) + coalesce(`religion_xp`,0)) + coalesce(`podcast_xp`,0)) + coalesce(`dic_xp`,0)) + coalesce(`exam_xp`,0)) + coalesce(`other_xp`,0))) STORED,
  `level` tinyint GENERATED ALWAYS AS ((case when (((((((((coalesce(`math_xp`,0) + coalesce(`science_xp`,0)) + coalesce(`persian_xp`,0)) + coalesce(`social_xp`,0)) + coalesce(`religion_xp`,0)) + coalesce(`podcast_xp`,0)) + coalesce(`dic_xp`,0)) + coalesce(`exam_xp`,0)) + coalesce(`other_xp`,0)) >= 7500) then 5 when (((((((((coalesce(`math_xp`,0) + coalesce(`science_xp`,0)) + coalesce(`persian_xp`,0)) + coalesce(`social_xp`,0)) + coalesce(`religion_xp`,0)) + coalesce(`podcast_xp`,0)) + coalesce(`dic_xp`,0)) + coalesce(`exam_xp`,0)) + coalesce(`other_xp`,0)) >= 3500) then 4 when (((((((((coalesce(`math_xp`,0) + coalesce(`science_xp`,0)) + coalesce(`persian_xp`,0)) + coalesce(`social_xp`,0)) + coalesce(`religion_xp`,0)) + coalesce(`podcast_xp`,0)) + coalesce(`dic_xp`,0)) + coalesce(`exam_xp`,0)) + coalesce(`other_xp`,0)) >= 1500) then 3 when (((((((((coalesce(`math_xp`,0) + coalesce(`science_xp`,0)) + coalesce(`persian_xp`,0)) + coalesce(`social_xp`,0)) + coalesce(`religion_xp`,0)) + coalesce(`podcast_xp`,0)) + coalesce(`dic_xp`,0)) + coalesce(`exam_xp`,0)) + coalesce(`other_xp`,0)) >= 500) then 2 else 1 end)) STORED,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Dumping data for table `student_xp`
