--
-- Triggers `student_xp`
--
DELIMITER $$
CREATE TRIGGER `update_student_level_before_insert` BEFORE INSERT ON `student_xp` FOR EACH ROW BEGIN
    SET NEW.level = CASE 
        WHEN NEW.total_xp >= 7500 THEN 5
        WHEN NEW.total_xp >= 3500 THEN 4
        WHEN NEW.total_xp >= 1500 THEN 3
        WHEN NEW.total_xp >= 500  THEN 2
        ELSE 1
    END;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `update_student_level_before_update` BEFORE UPDATE ON `student_xp` FOR EACH ROW BEGIN
    SET NEW.level = CASE 
        WHEN NEW.total_xp >= 7500 THEN 5
        WHEN NEW.total_xp >= 3500 THEN 4
        WHEN NEW.total_xp >= 1500 THEN 3
        WHEN NEW.total_xp >= 500  THEN 2
        ELSE 1
    END;
END
$$
DELIMITER ;

