--
-- Structure for view `podcast_stats`
--
DROP TABLE IF EXISTS `podcast_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`qwaepiuv`@`localhost` SQL SECURITY DEFINER VIEW `podcast_stats`  AS SELECT `p`.`id` AS `id`, `p`.`title` AS `title`, `p`.`topic` AS `topic`, `p`.`file_type` AS `file_type`, `p`.`created_at` AS `created_at`, count(distinct `pl`.`student_id`) AS `total_listeners`, coalesce(avg(`pl`.`completion_percent`),0) AS `avg_completion`, coalesce(sum(`pl`.`listen_duration`),0) AS `total_listen_time` FROM (`podcasts` `p` left join `podcast_listens` `pl` on((`p`.`id` = `pl`.`podcast_id`))) GROUP BY `p`.`id`, `p`.`title`, `p`.`topic`, `p`.`file_type`, `p`.`created_at` ;

-- --------------------------------------------------------

--
-- Structure for view `student_view`
--
DROP TABLE IF EXISTS `student_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`qwaepiuv`@`localhost` SQL SECURITY DEFINER VIEW `student_view`  AS SELECT `users`.`id` AS `id`, `users`.`username` AS `username`, `users`.`first_name` AS `first_name`, `users`.`last_name` AS `last_name`, `users`.`national_id` AS `national_id`, `users`.`birth_date` AS `birth_date`, concat(`users`.`first_name`,' ',`users`.`last_name`) AS `full_name`, `users`.`father_name` AS `father_name`, `users`.`father_phone` AS `father_phone`, `users`.`mother_name` AS `mother_name`, `users`.`mother_phone` AS `mother_phone`, `users`.`email` AS `email`, `users`.`created_at` AS `created_at`, `users`.`is_active` AS `is_active` FROM `users` WHERE (`users`.`user_type` = 'student') ;

